import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Überblick","description":"Die vier Wege, ApptiveGrid mit anderen Systemen zu verbinden.","frontmatter":{"title":"Überblick","description":"Die vier Wege, ApptiveGrid mit anderen Systemen zu verbinden."},"headers":[],"relativePath":"integrationen/ueberblick.md","filePath":"integrationen/ueberblick.md","lastUpdated":1786092153000}'),a={name:"integrationen/ueberblick.md"};function s(o,e,d,g,l,h){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="integrationen-im-uberblick" tabindex="-1">Integrationen im Überblick <a class="header-anchor" href="#integrationen-im-uberblick" aria-label="Permalink to &quot;Integrationen im Überblick&quot;">​</a></h1><p>ApptiveGrid lässt sich auf vier Wegen mit anderen Systemen verbinden.</p><table tabindex="0"><thead><tr><th>Weg</th><th>Richtung</th><th>Eingerichtet in</th></tr></thead><tbody><tr><td><strong>Integrationsschritte im Flow</strong></td><td>ApptiveGrid → Fremdsystem</td><td><a href="/docs/flows/aktionen">Flow-Editor</a></td></tr><tr><td><strong>Webhooks</strong></td><td>ApptiveGrid → Fremdsystem</td><td><a href="/docs/integrationen/webhooks">Space-Einstellungen</a></td></tr><tr><td><strong>Webhook-Auslöser</strong></td><td>Fremdsystem → ApptiveGrid</td><td><a href="/docs/flows/webhook-trigger">Flow-Editor</a></td></tr><tr><td><strong>Programmierschnittstelle</strong></td><td>beide Richtungen</td><td><a href="/docs/integrationen/api-zugangsdaten">API-Zugangsdaten</a></td></tr></tbody></table><hr><h2 id="welcher-weg-wofur" tabindex="-1">Welcher Weg wofür <a class="header-anchor" href="#welcher-weg-wofur" aria-label="Permalink to &quot;Welcher Weg wofür&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ziel</th><th>Weg</th></tr></thead><tbody><tr><td>Nachricht an Slack oder Teams schicken</td><td><strong>Integrationsschritt</strong></td></tr><tr><td>Kontakt in HubSpot anlegen</td><td><strong>Integrationsschritt</strong></td></tr><tr><td>Ein beliebiges System aufrufen</td><td><strong>Integrationsschritt</strong> <em>HTTP-Anfrage</em></td></tr><tr><td>Anderes System über Änderungen informieren</td><td><strong>Webhook</strong></td></tr><tr><td>Flow von außen starten</td><td><strong>Webhook-Auslöser</strong></td></tr><tr><td>Eigene Anwendung, die Daten liest und schreibt</td><td><strong>Programmierschnittstelle</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Erst prüfen, ob ein Flow reicht</p><p>Die Programmierschnittstelle ist mächtig, verlangt aber Programmierkenntnisse. Für die meisten Anbindungen genügt ein Flow mit dem Schritt <strong>HTTP-Anfrage</strong> — ganz ohne eigenen Code.</p></div><hr><h2 id="zugangsdaten-der-integrationsschritte" tabindex="-1">Zugangsdaten der Integrationsschritte <a class="header-anchor" href="#zugangsdaten-der-integrationsschritte" aria-label="Permalink to &quot;Zugangsdaten der Integrationsschritte&quot;">​</a></h2><p>Die fertigen Integrationsschritte unterscheiden sich darin, ob Sie eigene Zugangsdaten brauchen.</p><h3 id="ohne-eigene-zugangsdaten" tabindex="-1">Ohne eigene Zugangsdaten <a class="header-anchor" href="#ohne-eigene-zugangsdaten" aria-label="Permalink to &quot;Ohne eigene Zugangsdaten&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dienst</th><th>Sie geben ein</th></tr></thead><tbody><tr><td><strong>OpenAI</strong></td><td>Nur den Prompt und optionale Anweisungen</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">OpenAI läuft über ApptiveGrid</p><p>Sie brauchen <strong>keinen</strong> eigenen OpenAI-Vertrag und keinen API-Schlüssel. Der Schritt ist einsatzbereit, sobald Ihr Tarif ihn enthält.</p></div><div class="danger custom-block"><p class="custom-block-title">Prüfen Sie trotzdem, welche Daten Sie übergeben</p><p>Der Inhalt eines Prompts verlässt ApptiveGrid und wird an einen externen Dienst gesendet. Übergeben Sie keine personenbezogenen oder vertraulichen Daten ohne vorherige datenschutzrechtliche Prüfung.</p></div><h3 id="mit-eigenen-zugangsdaten" tabindex="-1">Mit eigenen Zugangsdaten <a class="header-anchor" href="#mit-eigenen-zugangsdaten" aria-label="Permalink to &quot;Mit eigenen Zugangsdaten&quot;">​</a></h3><p>Bei diesen Diensten brauchen Sie ein eigenes Konto und tragen die Zugangsdaten im jeweiligen Flow-Schritt ein:</p><table tabindex="0"><thead><tr><th>Dienst</th><th>Sie tragen ein</th><th>Woher Sie es bekommen</th></tr></thead><tbody><tr><td><strong>Slack</strong></td><td>Webhook-URL</td><td>Slack-Verwaltung, Incoming Webhook einrichten</td></tr><tr><td><strong>MS Teams</strong></td><td>Webhook-URL</td><td>Teams-Kanal, Connector einrichten</td></tr><tr><td><strong>Firebase Cloud Messaging</strong></td><td>API-Schlüssel, Geräte-Tokens oder Topic</td><td>Firebase-Konsole</td></tr><tr><td><strong>HubSpot</strong></td><td>API-Token</td><td>HubSpot-Konto</td></tr><tr><td><strong>Magenta Business</strong> (SMS, Verify)</td><td>API-Schlüssel und -Geheimnis</td><td>Vertrag mit dem Anbieter</td></tr><tr><td><strong>DATEV Lohn &amp; Gehalt</strong></td><td>Zugangsschlüssel und Passwort</td><td>Ihr DATEV-Zugang</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Zugangsdaten liegen im Flow</p><p>Die eingetragenen Schlüssel sind Teil der Flow-Konfiguration. Jede Person mit der Rolle <strong>Managen</strong> im Space kann den Flow öffnen.</p><p>Legen Sie Flows mit sensiblen Zugangsdaten deshalb in einem Space an, dessen Mitgliederkreis Sie bewusst klein halten — und verwenden Sie, wo möglich, Schlüssel mit eingeschränkten Rechten.</p></div><div class="tip custom-block"><p class="custom-block-title">Vor dem Aufbau die Zugangsdaten besorgen</p><p>Der häufigste Stolperstein: Der Flow ist fertig gebaut, aber der Slack-Webhook oder das HubSpot-Token fehlt noch — und dessen Beschaffung dauert in manchen Organisationen Tage.</p><p>Klären Sie das, bevor Sie mit dem Bauen beginnen.</p></div><h3 id="ohne-konfiguration-nutzbar" tabindex="-1">Ohne Konfiguration nutzbar <a class="header-anchor" href="#ohne-konfiguration-nutzbar" aria-label="Permalink to &quot;Ohne Konfiguration nutzbar&quot;">​</a></h3><p>Diese Schritte brauchen weder Vertrag noch Schlüssel:</p><p><strong>QR Code</strong>, <strong>PDF zu Text</strong>, <strong>URL zu PDF</strong>, <strong>CSV-Datei importieren</strong>, <strong>Sprache zu Text</strong>, <strong>Document Analyzer</strong>, <strong>Calendar Event</strong>, <strong>Warten</strong>, <strong>JavaScript</strong></p><p>Einige davon sind tarifgebunden.</p><hr><h2 id="wenn-kein-fertiger-schritt-passt" tabindex="-1">Wenn kein fertiger Schritt passt <a class="header-anchor" href="#wenn-kein-fertiger-schritt-passt" aria-label="Permalink to &quot;Wenn kein fertiger Schritt passt&quot;">​</a></h2><p>Der Schritt <strong>HTTP-Anfrage</strong> ruft beliebige Systeme auf. Sie geben selbst an:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Inhalt</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td>Zieladresse</td></tr><tr><td><strong>Methode</strong></td><td>GET, POST, …</td></tr><tr><td><strong>Content Type</strong></td><td>Format der Daten</td></tr><tr><td><strong>Headers</strong></td><td>Kopfzeilen, etwa zur Authentifizierung</td></tr><tr><td><strong>Inhalt</strong></td><td>Die zu sendenden Daten</td></tr><tr><td><strong>Benutzername</strong> / <strong>Password</strong></td><td>Für einfache Anmeldung</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Der Weg zu fast jedem Dienst</p><p>Alles, was eine offene Schnittstelle hat, lässt sich damit anbinden — auch Automatisierungsplattformen, die ihrerseits Hunderte Dienste erreichen.</p><p>Der Editor verweist selbst darauf: <em>Nichts passendes gefunden?</em> mit der Möglichkeit, eine Anfrage zu stellen.</p></div><hr><h2 id="wo-daten-liegen" tabindex="-1">Wo Daten liegen <a class="header-anchor" href="#wo-daten-liegen" aria-label="Permalink to &quot;Wo Daten liegen&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Dateianhänge</p><p>Hochgeladene Dateien liegen in einem Objektspeicher in der Region <strong>Europa (Frankfurt)</strong>. Für Uploads aus öffentlichen Formularen gibt es einen eigenen, nicht angemeldeten Weg.</p><p>Für datenschutzrechtliche Auskünfte wenden Sie sich an den Support — diese Dokumentation ersetzt keine rechtliche Bewertung.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/flows/aktionen">Aktionen</a> — alle Integrationsschritte im Detail</li><li><a href="/docs/integrationen/webhooks">Webhooks</a></li><li><a href="/docs/integrationen/api-zugangsdaten">API-Zugangsdaten</a></li></ul>',33)])])}const b=t(a,[["render",s]]);export{u as __pageData,b as default};
